/* Codes and passwords stay in form memory only; never saved to URLs or browser storage. */
function accountCodeFields(){return `<div class="formfield"><label for="auth-code">邮箱验证码</label><div class="auth-code-row"><input id="auth-code" name="code" required inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="one-time-code" placeholder="6位验证码"><button class="btn ghost" id="auth-send-code" type="button" onclick="sendAccountCode()">获取验证码</button></div></div><p id="auth-code-status" class="muted" role="status">${esc(state.authCodeMessage||'验证码10分钟内有效，仅可使用一次。')}</p>`}
function accountSecurityPage(){
 if(state.account){const user=state.account,canVerify=!user.phone&&!user.emailVerified;return `<main class="page wrap account-shell"><div class="account-intro"><span class="eyebrow">YOUR YICHEN</span><h1>你好，<span data-i18n-preserve>${esc(user.name)}</span>。</h1><p class="muted">查看已提交的用车需求，管理账户和邮箱验证。</p></div><div class="booking-content auth-card"><h2>我的账户</h2><p>${esc(user.phone||user.email)}</p><p class="account-verification">${user.phone?'手机号未验证 · 短信服务待开通':user.emailVerified?'邮箱已验证 · 可用于找回密码':'邮箱未验证 · 请完成归属验证'}</p>${canVerify?`<form data-auth-flow="verify" onsubmit="confirmAccountEmail(event)"><div class="formfield"><label for="auth-current-password">当前密码</label><input id="auth-current-password" type="password" required maxlength="128" autocomplete="current-password"></div>${accountCodeFields()}<p id="auth-error" role="alert" class="auth-error"></p><button id="auth-submit" class="btn">验证邮箱</button></form>`:''}<div class="hero-actions">${user.isOperator?'<a class="btn" href="./operator.html">管理客户需求 ↗</a>':''}<button class="btn ghost" onclick="nav('/trips')">查看我的旅程 ↗</button><button class="btn ghost" onclick="signOut()">退出登录</button></div></div></main>`}
 const mode=state.authMode||'login',register=mode==='register',forgot=mode==='forgot',offline=location.protocol==='file:';
 return `<main class="page wrap account-shell"><div class="account-intro"><span class="eyebrow">YOUR JOURNEY STARTS HERE</span><h1>每段旅程，<br>都有归处。</h1><p class="muted">验证邮箱后注册，提交需求并查看跟进状态。</p><div class="account-scene"><img src="${webImage(DEST[2].image)}" alt="四川雪山风景"></div></div><div class="booking-content auth-card"><div class="tabs"><button class="chip ${mode==='login'?'active':''}" onclick="setAuthMode('login')">登录</button><button class="chip ${register?'active':''}" onclick="setAuthMode('register')">注册</button></div><h2>${forgot?'找回密码':register?'创建你的账户':'欢迎回来'}</h2><p class="muted">${forgot?'使用已验证邮箱的验证码设置新密码。未验证的旧账号请先登录验证邮箱；无法登录时需人工核验。手机号账号暂需人工核验找回。':register?'先验证邮箱归属，再创建账户。短信验证未开通，暂不接受新的手机号注册。已有账号请登录或找回密码。':'使用已注册的手机号或邮箱与密码登录。'}</p>${offline?'<p role="alert">请通过网站服务打开账户页面。</p>':''}<form data-auth-flow="${mode}" onsubmit="${forgot?'submitPasswordReset(event)':'submitAccount(event)'}">${register?'<div class="formfield"><label for="auth-name">称呼</label><input id="auth-name" name="name" required maxlength="50" autocomplete="name"></div>':''}<div class="formfield"><label for="auth-email">${mode==='login'?'手机号 / 邮箱':'邮箱'}</label><input id="auth-email" name="account" type="${mode==='login'?'text':'email'}" required maxlength="254" autocomplete="${mode==='login'?'username':'email'}" oninput="clearAccountCode()" placeholder="${mode==='login'?'11位手机号或邮箱':'用于接收验证码的邮箱'}"></div>${mode!=='login'?accountCodeFields():''}<div class="formfield"><label for="auth-password">${forgot?'新密码':'密码'}</label><input id="auth-password" name="password" type="password" required minlength="10" maxlength="128" autocomplete="${mode==='login'?'current-password':'new-password'}" placeholder="至少10位字符"><button type="button" class="password-toggle" onclick="togglePassword('auth-password',this)" aria-pressed="false">显示密码</button></div>${mode!=='login'?'<div class="formfield"><label for="auth-confirm">确认密码</label><input id="auth-confirm" type="password" required minlength="10" maxlength="128" autocomplete="new-password"><button type="button" class="password-toggle" onclick="togglePassword(\'auth-confirm\',this)" aria-pressed="false">显示密码</button></div>':''}<p id="auth-error" class="auth-error" role="alert">${esc(state.authError||'')}</p><button id="auth-submit" class="btn" type="submit" ${offline?'disabled':''}>${forgot?'更新密码':register?'创建账户':'登录'} ↗</button></form>${mode==='login'?'<button class="link auth-forgot" onclick="setAuthMode(\'forgot\')">忘记密码？</button>':'<button class="link auth-forgot" onclick="setAuthMode(\'login\')">返回登录</button>'}<p class="muted auth-footnote">密码重设会退出该账号的所有登录。咨询提交不扣款、不锁车，车辆与报价需人工确认。</p></div></main>`;
}
function clearAccountCode(){state.authCodeEpoch=(state.authCodeEpoch||0)+1;state.authCodeUntil=0;const button=q('auth-send-code');if(button){button.disabled=false;button.textContent=t('获取验证码')}state.authChallengeId=null;state.authCodeMessage='';const code=q('auth-code');if(code)code.value='';const status=q('auth-code-status');if(status)status.textContent=t('邮箱变更后请重新获取验证码。')}
function authStatus(id,text){const el=q(id);if(el)el.textContent=text}
function mountAccountSecurity(){const button=q('auth-send-code');if(!button)return;const remaining=()=>Math.ceil(((state.authCodeUntil||0)-Date.now())/1000);if(remaining()<=0)return;button.disabled=true;const tick=()=>{const left=remaining();button.textContent=left>0?(state.lang==='en'?`${left}s to resend`:`${left}秒后重发`):t('重新获取');if(left<=0||!button.isConnected){clearInterval(timer);if(left<=0)button.disabled=false}};const timer=setInterval(tick,250);tick()}
async function sendAccountCode(){
 const button=q('auth-send-code');if(!button||button.disabled)return;
 const purpose=state.account?'verify':state.authMode==='forgot'?'reset':'register',email=(state.account?.email||q('auth-email')?.value||'').trim().toLowerCase(),input=q('auth-email'),epoch=state.authCodeEpoch||0;
 if(input&&!input.reportValidity())return;const current=q('auth-current-password');if(current&&!current.reportValidity())return;
 button.disabled=true;authStatus('auth-error','');
 try{const data=await accountRequest('/api/auth/email/send-code',{method:'POST',body:JSON.stringify({purpose,email,password:current?.value})});
  if(!button.isConnected||(state.authCodeEpoch||0)!==epoch)return;
  state.authChallengeId=data.challengeId;state.authCodeMessage=data.message;state.authCodeUntil=Date.now()+data.retryAfter*1000;authStatus('auth-code-status',t(data.message));mountAccountSecurity();
 }catch(e){if(button.isConnected&&(state.authCodeEpoch||0)===epoch){authStatus('auth-error',e.message);button.disabled=false}}
}

async function confirmAccountEmail(event){event.preventDefault();const button=q('auth-submit');if(button.disabled)return;button.disabled=true;try{const data=await accountRequest('/api/auth/email/verify',{method:'POST',body:JSON.stringify({challengeId:state.authChallengeId,code:q('auth-code').value})});state.account=data.user;state.authChallengeId=null;state.authCodeMessage='';render();toast(data.message)}catch(e){authStatus('auth-error',e.message)}finally{if(q('auth-submit'))q('auth-submit').disabled=false}}
async function submitPasswordReset(event){event.preventDefault();const button=q('auth-submit');if(button.disabled)return;if(q('auth-password').value!==q('auth-confirm').value){authStatus('auth-error','两次输入的密码不一致。');return}button.disabled=true;try{const data=await accountRequest('/api/auth/password/reset',{method:'POST',body:JSON.stringify({email:q('auth-email').value.trim(),challengeId:state.authChallengeId,code:q('auth-code').value,password:q('auth-password').value})});state.authChallengeId=null;state.authCodeMessage='';state.account=null;state.authMode='login';state.authError='';render();toast(data.message)}catch(e){authStatus('auth-error',e.message)}finally{if(q('auth-submit'))q('auth-submit').disabled=false}}
